  $('model').value=state.model;$('end').value=state.end;$('end-row').hidden=state.model!=='theta';$('direction').value=state.direction;$('direction-row').hidden=state.view==='newton';$('direction-note').textContent=state.view==='coupling'?'Increasing τ damps frozen relative perturbations; decreasing τ amplifies them.':'Direction changes playback, not the computed zero paths.';
  const count=state.model==='quartic'?4:3;if($('branch').children.length!==count){$('branch').replaceChildren();for(let i=0;i<count;i++){const option=node('option','',`Root ${i+1}`);option.value=i;$('branch').append(option);}}$('branch').value=state.branch;
