 function partialTrace(trace,travel,duration){const cutoff=travel*duration,points=trace.points||[],selected=[];for(let i=0;i<points.length;i++){const p=points[i];if((p.ell??0)<=cutoff){selected.push(p);continue;}if(i>0){const a=points[i-1],fraction=(cutoff-a.ell)/(p.ell-a.ell);if(fraction>0&&fraction<1)selected.push({sigma:a.sigma+fraction*(p.sigma-a.sigma),t:a.t+fraction*(p.t-a.t),ell:cutoff});}break;}return selected;}
