  const c=chart($('primary-plot'),{title:'Numerical continuous Newton guidance paths around the selected root',description:'The field is held fixed at the chosen heat parameter. Colored probe paths approach existing zeros. The paths do not move the zeros and can converge to off-line zeros in the exact quartet.',xMin:cx-extent,xMax:cx+extent,yMin:cy-extent,yMax:cy+extent,xLabel:'Real part σ',yLabel:'Height t',equal:true});
