  for(const trace of traces){const destination=typeof trace.destination==='number'?trace.destination:snap.roots.findIndex(r=>r.id===trace.destination),color=destination>=0?COLORS[destination%4]:'#768e9e',points=partialTrace(trace,travel,snap.state.newtonTime);pathLine(c,points.map(p=>[p.sigma,p.t]),color,1.5);const start=trace.points?.[0],end=points.at(-1);if(start)dot(c,start.sigma,start.t,'#627d8e',2.7,`Probe ${trace.id}`);if(end)dot(c,end.sigma,end.t,color,3.5);}
  for(const r of snap.roots){dot(c,r.sigma,r.t,COLORS[r.branch%4],r.branch===snap.state.branch?6:5,`Root ${r.branch+1}`);if(r.sigma>=cx-extent&&r.sigma<=cx+extent&&r.t>=cy-extent&&r.t<=cy+extent)svgText(c.svg,`ρ${r.branch+1}`,c.X(r.sigma)+12,c.Y(r.t)-9,{color:COLORS[r.branch%4],anchor:'start',size:11});}
