  $('primary-caption').textContent=`${traces.length} deterministic probes start around the selected root. The visible travel is ${Math.round(travel*100)}% of ℓ = ${snap.state.newtonTime}. Paths outside the displayed local square are clipped; their final statuses remain in the table.`;
  const converged=traces.filter(t=>String(t.status).includes('converg')).length,phaseErrors=traces.map(t=>t.phaseError).filter(finite),decayErrors=traces.map(t=>t.decayError).filter(finite),maxPhase=phaseErrors.length?Math.max(...phaseErrors):NaN,maxDecay=decayErrors.length?Math.max(...decayErrors):NaN;
  $('metric-strip').replaceChildren(metric('CONVERGED PROBES',`${converged} / ${traces.length}`,'Full numerical integration, not just visible travel'),metric('MAX PHASE DRIFT',fmt(maxPhase,4),'Measured along resolved paths, in radians'),metric('HEAT PARAMETER',fmt(snap.tau,8),'The function stays fixed during probe travel'));
